<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserInvitation\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\UserInvitation;
use Civi\Lughauth\Shared\Event\PublicEvent;

class UserInvitationUpdateEvent extends UserInvitationEvent implements PublicEvent
{
    public function __construct(
        UserInvitation $payload,
        public readonly UserInvitation $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'user-invitation.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
